var localeBinder = null

function normalizeLang(value) {
  if (typeof value !== 'string') return ''
  var lower = value.toLowerCase()
  if (lower.indexOf('zh') === 0) return 'zh'
  if (lower.indexOf('en') === 0) return 'en'
  return ''
}

